// Fragment rectangles inside the strip — xLo, xHi, width, height
const unsigned char g_Boss_Rects[] =
{
	0x00, 0x00, 0x44, 0x28,
	0x44, 0x00, 0x44, 0x28,
};
// g_Boss_Rects size: 8 Bytes

// Total size: 5480 Bytes

// Copies every frame into the off-screen strip at VRAM row `stripY`.
void g_Boss_Upload(UY stripY)
{
	VDP_CommandHMMC(g_Boss_Strip, 0, stripY, G_BOSS_STRIP_W, G_BOSS_STRIP_H);
}

// Puts back what the object was covering. Safe before the first draw.
void g_Boss_Restore(g_Boss_SwSprite* s, UY stripY)
{
	if(s->bw == 0)
		return;
	VDP_CommandHMMM(s->slot * G_BOSS_BACKUP_PITCH, stripY + G_BOSS_STRIP_H, s->bx, s->by, s->bw, s->bh);
	s->bw = 0;
}

// Saves the background at the new position, then blits `frame` over it.
void g_Boss_Draw(g_Boss_SwSprite* s, u8 frame, UX x, UY y, UY stripY)
{
	const u8* rect = g_Boss_Rects + ((u16)frame * 4);
	UX sx = rect[0] + ((u16)rect[1] << 8);
	u8  w  = rect[2];
	u8  h  = rect[3];
	// HMMM copies whole bytes, so the backup starts a couple of dots early
	// and runs wider — otherwise the sprite leaves its edges behind.
	s->bx = (x > 2) ? x - 2 : 0;
	s->by = y;
	s->bw = w + 4;
	s->bh = h;
	VDP_CommandHMMM(s->bx, y, s->slot * G_BOSS_BACKUP_PITCH, stripY + G_BOSS_STRIP_H, s->bw, h);
	VDP_CommandLMMM(sx, stripY, x, y, w, h, VDP_OP_TIMP);
}
